    '''from __future__ import annotations\n\nimport json\nfrom time import perf_counter\n\nfrom src.engines.v4_decision_pipeline import _semantic_fingerprint, effective_planning_squad\nfrom src.engines.v4_full_universe_package_shard_merge import merge_exact_package_shards\nfrom src.engines.v4_package_artifact_contract import MANIFEST_OUTFILE, PACKAGE_OUTFILE, TACTICAL_INTERACTION_OUTFILE, current_input_digests, sha256_path\nfrom src.engines.v4_tactical_interaction import build_tactical_interactions\nfrom src.engines.v4_wc_optimizer import build_candidates\nfrom src.services.package_optimization_execution_plan import load_execution_plan\nfrom src.utils import CONFIG, DATA, atomic_json, iso_now, read_json\n\n\ndef run() -> dict:\n    plan=load_execution_plan(); oc=int(plan["partition"]["outgoing"]["shard_count"]); ic=int(plan["partition"]["incoming_prefix"]["shard_count"]); expected=oc*ic\n    paths=sorted((DATA/"package_shards").glob("cell-o*-i*.json")); wrappers=[read_json(p,{}) for p in paths]\n    if len(wrappers)!=expected: raise RuntimeError(f"expected {expected} exact shard cells, got {len(wrappers)}")\n    if any(w.get("execution_registry")!=plan["registry"] for w in wrappers): raise RuntimeError("shard execution-registry lineage mismatch")\n    semantic={str(w.get("semantic_fingerprint") or "") for w in wrappers}; raw={json.dumps(w.get("input_sha256") or {},sort_keys=True) for w in wrappers}\n    if len(semantic)!=1 or len(raw)!=1: raise RuntimeError("shard input lineage mismatch")\n    predictions=read_json(DATA/"predictions_v4.json",{}); universe=read_json(DATA/"universe.json",{}); locked=read_json(CONFIG/"locked_squad.json",{}); understat=read_json(DATA/"understat_v4.json",{}); prices=read_json(DATA/"prices.json",{})\n    planning=effective_planning_squad(locked,predictions); locked_for_search=dict(locked); locked_for_search["players"]=list(planning.get("players") or [])\n    for key in ("bank","free_transfers","transfer_cost_points","free_hit_active"): locked_for_search[key]=planning.get(key,locked.get(key))\n    candidates=build_candidates(predictions); tactical=build_tactical_interactions(predictions,universe,understat,team_system_evidence=read_json(DATA/"team_system_evidence_v4.json",{}),roster_events=read_json(DATA/"roster_events_v4.json",{}))\n    current=_semantic_fingerprint(candidates,locked_for_search,predictions=predictions,universe=universe,understat=understat,tactical_interactions=tactical,prices=prices)\n    if current!=next(iter(semantic)): raise RuntimeError("fan-in semantic fingerprint stale")\n    started=perf_counter(); merged=merge_exact_package_shards([w["result"] for w in wrappers]); merge_ms=round((perf_counter()-started)*1000,3)\n    atomic_json(TACTICAL_INTERACTION_OUTFILE,tactical); atomic_json(PACKAGE_OUTFILE,merged)\n    max_worker=max(float(w.get("duration_ms") or 0) for w in wrappers); wall=max_worker+merge_ms; worker_slo=float(plan["worker"]["slo_ms"]); merge_slo=float(plan["fan_in"]["slo_ms"]); wall_slo=float(plan["precompute"]["wall_slo_ms"]); ok=max_worker<worker_slo and merge_ms<merge_slo and wall<wall_slo\n    if not ok: raise RuntimeError(f"package precompute SLO failed worker={max_worker} merge={merge_ms} wall={wall}")\n    manifest={"schema_version":2,"contract":"V4_EXACT_PACKAGE_OPTIMIZATION_MANIFEST_V1","generated_at":iso_now(),"status":"PASS","slo_status":"PASS","duration_ms":round(wall,3),"slo_ms":wall_slo,"input_sha256":current_input_digests(),"semantic_fingerprint":current,"package_artifact_sha256":sha256_path(PACKAGE_OUTFILE),"tactical_interaction_sha256":sha256_path(TACTICAL_INTERACTION_OUTFILE),"search":{"status":"FULL_UNIVERSE_PROVEN","authoritative_for_recommendation":True,"decision_authority":"ENGINE_ADVISORY_ONLY_FULL_UNIVERSE_PROVEN","heuristic_candidate_cutoff":False,"beam_cutoff":False},"execution":{"registry":plan["registry"],"topology":plan["topology"],"worker_count":expected,"outgoing_shard_count":oc,"incoming_prefix_shard_count":ic,"max_shard_duration_ms":max_worker,"merge_duration_ms":merge_ms},"guardrails":{"full_universe_exact_search_owner":True,"decision_consumer_recompute_forbidden":True,"input_lineage_fail_closed":True,"package_slo_separate_from_decision_compute_slo":True,"workflow_matrix_fanout_fanin":True,"all_shards_non_authoritative":True,"fan_in_single_global_authority":True,"shard_partition_disjointness_proven":True,"shard_partition_completeness_proven":True,"execution_registry_authoritative":True,"monolithic_fallback_forbidden":True}}\n    atomic_json(MANIFEST_OUTFILE,manifest); print(json.dumps({"service":"package_optimization_merge","status":"PASS","workers":expected,"max_worker_ms":max_worker,"merge_ms":merge_ms,"wall_ms":wall},ensure_ascii=False)); return manifest\n\n\nif __name__ == "__main__": run()\n''',
