write("tests/test_v4_exact_workflow_shard_merge.py", '''from __future__ import annotations\n\nimport pytest\nfrom src.engines.v4_full_universe_package_shard_merge import merge_exact_package_shards\n\n\ndef _cell(pid, score, o, i, oc=2, ic=2):\n    pkg={"package_id":pid,"replacements":1,"adjusted_utility_gain_5":score,"adjusted_best_xi_gain_5":score,"net_xpts_3":score,"net_xpts_5":score,"net_xpts_10":score,"net_xpts_15":score,"target_cost":1000,"target_itb":0,"hit_cost":0,"projection_uncertainty":0.1,"xmins_uncertainty":0.1,"tactical_uncertainty":0.1,"roster_change_uncertainty":0.1,"price_risk":0.1,"tactical_role_confidence":0.9,"opponent_matchup_confidence":0.9,"structural_flexibility":0.5,"classification":"IMPROVE"}\n    roll=dict(pkg,package_id="ROLL_BASELINE",replacements=0,adjusted_utility_gain_5=0.0,classification="ROLL_BASELINE")\n    keys=[f"1:{o}"]; return {"contract":"V4_FULL_UNIVERSE_PACKAGE_SEARCH_V1","overall_verdict":"IMPROVE","recommended_package":pkg,"roll_baseline":roll,"baseline":{"x":1},"affordability":{"x":1},"best_by_replacement_count":{"1":pkg},"packages":[pkg],"efficient_frontier":{"status":"SHARD_PARTIAL","dominance_epsilon":0.01,"rows":[roll,pkg],"maximize":[],"minimize":[]},"search":{"status":"SHARD_PARTIAL_EXACT","authoritative_for_recommendation":False,"outgoing_shard_index":o,"outgoing_shard_count":oc,"incoming_prefix_shard_index":i,"incoming_prefix_shard_count":ic,"maximum_replacements":3,"heuristic_candidate_cutoff":False,"beam_cutoff":False,"proof_covers_package_frontier_risk_confidence":True,"proof_covers_projected_affordability":True,"proof_covers_recommendation_sanity":True,"proof_minimize_dimensions":["a"],"proof_maximize_dimensions":["b"],"pruning_proofs":[],"diagnostics":{"outgoing_jobs_total":oc,"outgoing_jobs_selected":1,"outgoing_job_keys":keys,"incoming_prefixes_total":ic,"incoming_prefixes_selected":1,"packages_evaluated":1}},"decision_authority":"SHARD_PARTIAL_NO_AUTHORITY","governance":{}}\n\n\ndef test_2d_fan_in_requires_complete_cartesian_coverage():\n    merged=merge_exact_package_shards([_cell(f"P{o}{i}",float(o*2+i+1),o,i) for o in range(2) for i in range(2)])\n    assert merged["search"]["status"]=="FULL_UNIVERSE_PROVEN"; assert merged["search"]["authoritative_for_recommendation"] is True\n    d=merged["search"]["diagnostics"]; assert d["workflow_worker_count"]==4; assert d["outgoing_partitions_complete"] is True; assert d["incoming_prefix_partitions_complete"] is True; assert d["shard_partitions_complete"] is True\n\n\ndef test_2d_fan_in_rejects_missing_coordinate_or_prefix_gap():\n    cells=[_cell(f"P{o}{i}",1.0,o,i) for o in range(2) for i in range(2)]\n    with pytest.raises(RuntimeError): merge_exact_package_shards(cells[:-1])\n    cells[0]["search"]["diagnostics"]["incoming_prefixes_selected"]=0\n    with pytest.raises(RuntimeError): merge_exact_package_shards(cells)\n''')

